"""Fresh periodic finite-difference matrices in the original axis order."""

import numpy as np
import numpy.typing as npt


def laplacian_1d(size: int) -> npt.NDArray[np.complex128]:
    """Return (S-minus - 2I + S-plus)/4 at the declared periodic size."""
    if type(size) is not int or not 2 <= size <= 32 or size & (size - 1):
        raise ValueError("grid size must be a power of two in 2..32")
    shift = np.zeros((size, size), dtype=np.complex128)
    for column in range(size):
        shift[(column + 1) % size, column] = 1
    return np.asarray(
        (shift.conj().T - 2 * np.eye(size) + shift) / 4, dtype=np.complex128
    )


def laplacian_nd(sizes: tuple[int, ...]) -> npt.NDArray[np.complex128]:
    """Retain the source reversed Kronecker order and power-of-two selector scale."""
    if not sizes or len(sizes) > 4:
        raise ValueError("one to four periodic dimensions are supported")
    matrices = tuple(laplacian_1d(size) for size in sizes)
    total = int(np.prod(sizes))
    if total > 256:
        raise ValueError("bounded matrix reference supports at most 256 grid points")
    result = np.zeros((total, total), dtype=np.complex128)
    for axis in range(len(sizes)):
        factors = tuple(
            matrices[index] if index == axis else np.eye(size, dtype=np.complex128)
            for index, size in enumerate(sizes)
        )
        term = factors[-1]
        for factor in reversed(factors[:-1]):
            term = np.asarray(np.kron(term, factor), dtype=np.complex128)
        result += term
    return result / (1 << (len(sizes) - 1).bit_length())

"""Independent coordinate-shift permutation in original packed-register order."""

import torch

import flagquantum as fq
from examples.synthesis.community.paper_implementation_project.block_encoding_nd_laplacian.periodic_laplacian_nd.main import (
    build_program,
)
from examples.synthesis.compare_states import compare_states


def reference_circuit(
    position: int = 0, selector: int = 0, dimension: int = 0, coherent: bool = False
) -> fq.Circuit:
    circuit = fq.Circuit(6, dtype=torch.complex128)
    word = 8 * position + 2 * selector + dimension
    for wire in range(6):
        if word & (1 << (5 - wire)):
            circuit.x(wire)
    if coherent:
        for wire, angle in enumerate((0.26, 0.13, 0.39, 0.52, 0.65, 0.78)):
            circuit.h(wire).phase(wire, theta=angle)
    circuit.h(3).h(4).z(3).z(4).h(5)
    shift = torch.zeros((64, 64), dtype=torch.complex128)
    for position in range(8):
        for selector in range(4):
            for dimension in range(2):
                low, high = position & 1, position >> 1
                delta = -int(not (selector & 1)) + int(bool(selector & 2))
                if dimension:
                    high = (high + delta) % 4
                else:
                    low = (low + delta) % 2
                target = 2 * high + low
                shift[
                    8 * target + 2 * selector + dimension,
                    8 * position + 2 * selector + dimension,
                ] = 1
    circuit.any(*range(6), matrix=shift)
    return circuit.h(3).h(4).h(5)


def run_example() -> None:
    compare_states(
        build_program(), reference_circuit(), ("j1", "j0", "selector", "dimension")
    )


if __name__ == "__main__":
    run_example()

"""Reference the two conditional cyclic shifts as an exact basis permutation."""

import torch

import flagquantum as fq
from examples.synthesis.community.paper_implementation_project.block_encoding_nd_laplacian.periodic_laplacian_1d.main import (
    build_program,
)
from examples.synthesis.compare_states import compare_states


def reference_circuit(
    position: int = 0, selector: int = 0, coherent: bool = False
) -> fq.Circuit:
    circuit = fq.Circuit(7, dtype=torch.complex128)
    for wire in range(5):
        if position & (1 << (4 - wire)):
            circuit.x(wire)
    for bit in range(2):
        if selector & (1 << bit):
            circuit.x(6 - bit)
    if coherent:
        for wire in range(5):
            circuit.h(wire).phase(wire, theta=0.13 * (1 << (4 - wire)))
    circuit.h(5).h(6).z(5).z(6)
    shift = torch.zeros((128, 128), dtype=torch.complex128)
    for position in range(32):
        for selector in range(4):
            low, high = selector & 1, selector >> 1
            target = (position - (1 - low) + high) % 32
            shift[4 * target + selector, 4 * position + selector] = 1
    circuit.any(*range(7), matrix=shift)
    return circuit.h(5).h(6).z(5).z(6)


def run_example() -> None:
    compare_states(build_program(), reference_circuit(), ("position", "selector"))


if __name__ == "__main__":
    run_example()
